INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(29401, '2 Peter 3:12', '2 Peter', 3, 12, '&nbsp;تاسو د خُدائ پاک د هغه ورځې د راتلو اِنتظار کوئ چې هغه زر راشى چې د کومې په وجه به آسمانونه په اور کښې وسوزى او برباد به شى، او ستورى او سيارې به د اور د تاو نه ويلى شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29402, '2 Peter 3:13', '2 Peter', 3, 13, '&nbsp;خو د هغۀ د لوظ په مطابق مونږ د نوؤ آسمانونو او نوې دُنيا اِنتظار کوُو چې د صداقت نه ډکه وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29403, '2 Peter 3:14', '2 Peter', 3, 14, '&nbsp;په دې وجه زما ګرانو دوستانو، کله چې تاسو د دې خبرو په اِنتظار کښې يئ نو کوشش کوئ چې کله د هغۀ سره مخامخ کېږئ نو چې د سلامتۍ په حالت کښې بې‌داغه او بې‌عېبه يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29404, '2 Peter 3:15', '2 Peter', 3, 15, '&nbsp;او تاسو زمونږ د مالِک صبر لکه د خلاصون وګڼئ نو دغسې زمونږ خوږ ورور پولوس هم د خپل ورکړے شوى حِکمت په مطابق درته وليکل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29405, '2 Peter 3:16', '2 Peter', 3, 16, '&nbsp;او په خپلو ټولو خطونو کښې يې دا خبرې ليکلى دى. په هغوئ کښې ځينې خبرې داسې دى چې پرې پوهېدل ګران دى، او جاهلان او سپک خلق د دې معنىٰ بدلوى لکه څنګه چې هغوئ د نورو صحيفو معنىٰ بدلوى او د ځانونو دپاره هلاکت پېدا کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29406, '2 Peter 3:17', '2 Peter', 3, 17, '&nbsp;زما ګرانو دوستانو، څنګه چې تاسو د اول نه خبر يئ، نو بېدار اوسئ چې د بې‌دينو خلقو په غلطيانو سره بې‌لارې نۀ شئ، او خپل مضبوطوالے پرې نۀ ږدئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29407, '2 Peter 3:18', '2 Peter', 3, 18, '&nbsp;بلکې زمونږ د مالِک او خلاصوونکى عيسىٰ مسيح په فضل او عِلم کښې ترقى وکړئ. د هغۀ جلال دې اوس هم وى او تل تر تله دې وى. آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29408, '1 John 1:1', '1 John', 1, 1, '&nbsp;مونږ تاسو ته د هغه کلام په حقله بيان وکړو کوم چې د ازل نه موجود وو، کوم چې مونږ واورېدو او په خپلو سترګو مو وليدلو. مونږ يې ننداره وکړه او خپل لاسونه مو ورسره ولګول. هغه د ژوندون کلام دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29409, '1 John 1:2', '1 John', 1, 2, '&nbsp;دا ژوندون مونږ ته ښکاره کړے شوے وو او مونږ هغه ليدلے دے، او مونږ يې ګواهى کوُو او تاسو ته وايو چې هغه هغه څوک دے چې خپله د تل ژوندون دے. هغه پلار سره وو او بيا مونږ ته ظاهر شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29410, '1 John 1:3', '1 John', 1, 3, '&nbsp;څۀ چې مونږ ليدلى او اورېدلى دى، مونږ هغه تاسو ته بيانوو د دې دپاره چې تاسو مونږ سره په کښې شريک شئ او په رښتيا مونږ د پلار او د هغۀ د زوئ عيسىٰ مسيح سره شراکت وساتو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29411, '1 John 1:4', '1 John', 1, 4, '&nbsp;مونږ دا څيزونه ځکه ليکُو چې زمونږ خوشحالى پوره شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29412, '1 John 1:5', '1 John', 1, 5, '&nbsp;دا هغه پېغام دے چې مونږ د مسيح نه واورېدلو او تاسو ته يې معلومات درکوو چې خُدائ پاک نُور دے او په هغۀ کښې هيڅ تيارۀ نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29413, '1 John 1:6', '1 John', 1, 6, '&nbsp;کۀ مونږ دا وايو چې هغۀ سره شراکت ساتو او په تيارو کښې ګرځو نو مونږ دروغژن يُو او په هغې عمل نۀ کوُو څۀ چې رښتيا دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29414, '1 John 1:7', '1 John', 1, 7, '&nbsp;خو کۀ مونږ په نُور کښې ژوند کوُو لکه څنګه چې هغه په خپله په نُور کښې دے نو بيا مونږ په خپلو کښې شراکت ساتو، او د هغۀ د زوئ عيسىٰ وينه مونږ د هر يو ګناه نه پاکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29415, '1 John 1:8', '1 John', 1, 8, '&nbsp;کۀ چرې مونږ دا وايو چې بې‌ګناه يُو نو په دې مونږ خپل ځان له دوکه ورکوو او په مونږ کښې رښتيا نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29416, '1 John 1:9', '1 John', 1, 9, '&nbsp;خو کۀ مونږ د خپلو ګناهونو اِقرار وکړُو نو هغه چې وفادار او صادق دے، هغه به زمونږ ګناهونه معاف کړى او مونږ به د هر قِسمه بدو نه پاک کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29417, '1 John 1:10', '1 John', 1, 10, '&nbsp;کۀ چرې مونږ دا وايو چې مونږ هيڅ ګناه نۀ ده کړې نو مونږ خُدائ پاک دروغژن کوُو او د هغۀ کلام په مونږ کښې نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29418, '1 John 2:1', '1 John', 2, 1, '&nbsp;زما ګرانو بچو، د دغو خبرو د ليکلو نه زما مطلب دا دے چې تاسو ګناه ونۀ کړئ، خو کۀ څوک ګناه وکړى نو د پلار سره زمونږ يو شفاعت کوونکے دے، يعنې عيسىٰ مسيح چې صادق دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29419, '1 John 2:2', '1 John', 2, 2, '&nbsp;او هغه زمونږ د ګناهونو کفاره دے، او هغه نۀ يواځې زمونږ د ګناهونو بلکې د ټولې دُنيا د ګناهونو کفاره هم دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29420, '1 John 2:3', '1 John', 2, 3, '&nbsp;کۀ مونږ د هغۀ په حکمونو عمل کوُو نو دا د دې خبرې ثبوت دے چې مونږ هغه پېژنو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29421, '1 John 2:4', '1 John', 2, 4, '&nbsp;کۀ څوک وائى چې، ”زۀ يې پېژنم،“ خو بيا هم د هغۀ په حُکمونو عمل نۀ کوى نو هغه دروغژن دے او په داسې کس کښې رښتيا نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29422, '1 John 2:5', '1 John', 2, 5, '&nbsp;خو څوک چې د هغۀ په کلام عمل کوى نو په دغه کس کښې د خُدائ پاک مينه کامله شوې ده. نو مونږ بيا په دې پوهيږو چې په رښتيا په هغۀ کښې اوسيږو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29423, '1 John 2:6', '1 John', 2, 6, '&nbsp;هر څوک چې وائى چې، ”زۀ په هغۀ کښې اوسېږم،“ نو په کار دى چې هغه دې داسې ژوند تېروى لکه څنګه چې مسيح تېر کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29424, '1 John 2:7', '1 John', 2, 7, '&nbsp;ګرانو دوستانو، زۀ تاسو ته څۀ نوے حُکم نۀ ليکم، بلکې دا هغه زوړ حُکم دے چې د شروع نه تاسو سره دے. دا زوړ حُکم هغه کلام دے کوم چې تاسو د مخکښې نه اورېدلے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29425, '1 John 2:8', '1 John', 2, 8, '&nbsp;نو بيا هم زۀ تاسو ته يو نوے حُکم ليکم چې هغه په رښتيا د مسيح او ستاسو په ژوندون ليدلے کيږى ځکه چې تيارۀ ختميږى او رښتينے نُور اوس هم ځليږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29426, '1 John 2:9', '1 John', 2, 9, '&nbsp;کۀ څوک دا دعوىٰ کوى چې، ”زۀ په نُور کښې يم،“ او هغه د خپل ورور يا خور نه نفرت کوى نو هغه اوس هم هغه شان په تيارۀ کښې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29427, '1 John 2:10', '1 John', 2, 10, '&nbsp;هر څوک چې د خپل ورور يا خور سره مينه کوى، هغه په نُور کښې ژوند تېروى او داسې کس هيچرې د تيندک سبب نۀ جوړيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29428, '1 John 2:11', '1 John', 2, 11, '&nbsp;خو هر څوک چې د خپل ورور يا خور نه نفرت کوى، هغه په تيارۀ کښې ګرځى بلکې په تيارۀ کښې ژوند تېروى او هغه نۀ پوهيږى چې چرته روان دے ځکه چې تيارې د هغۀ سترګې ړندې کړې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29429, '1 John 2:12', '1 John', 2, 12, '&nbsp;زما ګرانو بچو، زۀ تاسو ته ليکم ځکه چې ستاسو ګناهونه د مسيح په نوم معاف کړے شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29430, '1 John 2:13', '1 John', 2, 13, '&nbsp;اے مشرانو، زۀ تاسو ته ليکم ځکه چې تاسو هغه پېژنئ څوک چې ازلى دے. اے ځوانانو، زۀ تاسو ته ځکه ليکم چې تاسو هغه چا ته څوک چې شرير دے شکست ورکړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29431, '1 John 2:14', '1 John', 2, 14, '&nbsp;اے بچو، زۀ تاسو ته ځکه ليکم چې تاسو پلار پېژنئ. اے مشرانو، زۀ تاسو ته ځکه ليکم چې تاسو هغه پېژنئ څوک چې د ازل نه دے. اے ځوانانو، زۀ تاسو ته ځکه ليکم چې تاسو مضبوط يئ او د خُدائ پاک کلام په تاسو کښې پاتې کيږى او تاسو په هغۀ څوک چې شرير دے غالب شوى يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29432, '1 John 2:15', '1 John', 2, 15, '&nbsp;د دُنيا او د هغې د څيزونو سره مينه مۀ کوئ، ځکه چې څوک چې د دُنيا سره مينه کوى، په هغوئ کښې د پلار مينه نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29433, '1 John 2:16', '1 John', 2, 16, '&nbsp;ځکه چې په دُنيا کښې د نفس خواهش، يا د سترګو شوق، او يا د دولت غرور، دا د پلار د طرفه نۀ دى بلکې دُنياوى څيزونه دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29434, '1 John 2:17', '1 John', 2, 17, '&nbsp;دُنيا او د هغې شوق تېرېدونکى دى، خو څوک چې د خُدائ پاک په مرضۍ عمل کوى هغه به تل تر تله ژوندے وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29435, '1 John 2:18', '1 John', 2, 18, '&nbsp;زما ګرانو بچو، دا آخرى وخت دے. څنګه چې تاسو اورېدلى دى چې خردجال راتلونکے دے، نو اوس ډېر خردجالان راپورته شوى دى، او د دې نه مونږ په دې پوهيږو چې دا آخرى وخت دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29436, '1 John 2:19', '1 John', 2, 19, '&nbsp;هغوئ زمونږ د قبيلې نه ووتل ځکه چې د هغوئ مونږ سره په رښتيا تعلق نۀ وو، نو کۀ چرې هغوئ زمونږ وے نو هغوئ به مونږ سره تعلق ساتلو. کله چې هغوئ لاړل نو د دې نه دا ثابته شوه چې هغوئ زمونږ نۀ وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29437, '1 John 2:20', '1 John', 2, 20, '&nbsp;خو تاسو په روحُ القُدس مسح کړے شوى يئ او تاسو ټولو ته د حقيقت پته ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29438, '1 John 2:21', '1 John', 2, 21, '&nbsp;ما درته دا نۀ دى ليکلى چې ګنې تاسو د رښتياو نه ناخبره يئ بلکې تاسو پرې خبر يئ، او د دروغو د رښتياو سره څۀ تعلق نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29439, '1 John 2:22', '1 John', 2, 22, '&nbsp;دروغژن څوک دے؟ هغه څوک چې وائى چې عيسىٰ مسيح نۀ دے، نو دا خردجال دے څوک چې د پلار او زوئ دواړو نه اِنکار کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29440, '1 John 2:23', '1 John', 2, 23, '&nbsp;هر څوک چې د زوئ نه اِنکار کوى هغۀ سره پلار هم نشته، او هر څوک چې د زوئ اِقرار کوى نو هغۀ سره پلار هم شته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29441, '1 John 2:24', '1 John', 2, 24, '&nbsp;تاسو چې اول نه څۀ اورېدلى دى، هغه په خپلو زړُونو کښې وساتئ. او څۀ چې تاسو د اول نه اورېدلى دى، کۀ هغه تاسو کښې وى نو تاسو به په خپله هم په زوئ او پلار دواړو کښې پاتې شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29442, '1 John 2:25', '1 John', 2, 25, '&nbsp;او کومه وعده چې هغۀ مونږ سره کړې ده هغه د تل ژوندون دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29443, '1 John 2:26', '1 John', 2, 26, '&nbsp;زۀ دا خبرې تاسو ته د هغه چا په باب کښې ليکم څوک چې ستاسو د دوکه کولو کوشش کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29444, '1 John 2:27', '1 John', 2, 27, '&nbsp;کوم روحُ القُدس چې تاسو مسح کړى يئ هم هغه په تاسو کښې اوسى، نو بيا تاسو ته د بل اُستاذ ضرورت نشته. نو چې روحُ القُدس تاسو ته د هر څۀ په حقله تعليم درکوى، او څۀ چې درته هغه ښائى، رښتيا دى، نه چې دروغ، او څنګه تعليم چې هغۀ درکړے دے په هغۀ کښې پاتې شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29445, '1 John 2:28', '1 John', 2, 28, '&nbsp;اوس اے ګرانو بچو، اوس په هغۀ کښې شراکت وساتئ، نو کله چې هغه ښکاره شى نو مونږ به مطمئن يُو او د هغۀ په راتلو به د هغۀ په وړاندې شرمنده نۀ يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29446, '1 John 2:29', '1 John', 2, 29, '&nbsp;کۀ تاسو ته پته وى چې مسيح صادق دے نو تاسو به په دې مطمئن شئ چې څوک صداقت کوى هغه د خُدائ پاک روحانى بچى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29447, '1 John 3:1', '1 John', 3, 1, '&nbsp;تاسو وګورئ چې پلار مونږ ته څومره زياته مينه راکړه چې مونږ به د خُدائ پاک روحانى بچى بللے شُو، نو مونږ په رښتيا سره هم دغه شان يُو. او دُنيا چې مونږ نۀ پېژنى هغه ځکه چې هغه يې هم نۀ دے پېژندلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29448, '1 John 3:2', '1 John', 3, 2, '&nbsp;ګرانو دوستانو، مونږ اوس د خُدائ پاک روحانى بچى يُو خو چې څنګه به يُو هغه لا تر اوسه راته پته نشته، خو مونږ په دې پوهيږو چې کله عيسىٰ راښکاره شى نو مونږ به د هغۀ په شان يُو، ځکه چې مونږ به يې هم په هغه شان ووينو څنګه چې هغه دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29449, '1 John 3:3', '1 John', 3, 3, '&nbsp;او هغه ټول چې په مسيح دا اُميد ساتى، نو هغوئ ځانونه داسې پاک ساتى لکه چې مسيح دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29450, '1 John 3:4', '1 John', 3, 4, '&nbsp;هر څوک چې ګناه کوى، هغه بې‌شرعې کارونه کوى، ګناه خو بې‌شرعې کارونه کول دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29451, '1 John 3:5', '1 John', 3, 5, '&nbsp;تاسو ته پته ده چې مسيح ځکه راغلو چې ګناهونه اخوا کړى، او په هغۀ کښې هيڅ ګناه نشته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29452, '1 John 3:6', '1 John', 3, 6, '&nbsp;څوک هم چې په مسيح کښې اوسى، هغه به ګناه نۀ کوى، خو څوک چې په ګناه کښې لګيا وى، نۀ هغۀ مسيح ليدلے او نۀ يې پېژنى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29453, '1 John 3:7', '1 John', 3, 7, '&nbsp;زما بچو، څوک دې هم تاسو دوکه نۀ کړى ځکه چې څوک هم صداقت کوى هغه صادق دے لکه چې مسيح صادق دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29454, '1 John 3:8', '1 John', 3, 8, '&nbsp;خو څوک چې هر وخت ګناه کوى، هغه د اِبليس بچے دے ځکه چې اِبليس د ازل نه په ګناه کولو کښې آخته دے. او د خُدائ پاک زوئ د دې مقصد دپاره ظاهر شو چې د اِبليس کارونه برباد کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29455, '1 John 3:9', '1 John', 3, 9, '&nbsp;خو څوک چې د خُدائ پاک روحانى بچى دى هغوئ قصداً ګناه نۀ کوى ځکه چې په هغۀ کښې د خُدائ پاک ذات قائم وى، نو هغه ګناه نۀ کوى ځکه چې هغه د خُدائ پاک بچے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29456, '1 John 3:10', '1 John', 3, 10, '&nbsp;هم دغه د خُدائ پاک د بچو او د اِبليس په بچو کښې فرق دے، څوک چې په صداقت عمل نۀ کوى هغه د خُدائ پاک نه نۀ دے، او نۀ هغه څوک چې د خپل ورور سره مينه نۀ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29457, '1 John 3:11', '1 John', 3, 11, '&nbsp;نو دا هغه پېغام دے چې د شروع نه تاسو اورېدلے دے، هغه دا چې مونږ دې د يو بل سره مينه کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29458, '1 John 3:12', '1 John', 3, 12, '&nbsp;مونږ دې د قائِن په شان جوړ نۀ شو څوک چې د شرير نه وو او خپل ورور يې قتل کړو. او هغۀ هغه ولې قتل کړو؟ ځکه چې د هغۀ خپل عمل بد وُو او د هغۀ د ورور عمل د صداقت وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29459, '1 John 3:13', '1 John', 3, 13, '&nbsp;زما وروڼو او خوېندو، په دې حېرانېږئ مه چې دُنيا تاسو نه نفرت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29460, '1 John 3:14', '1 John', 3, 14, '&nbsp;کۀ چرې مونږ خپلو ايماندارانو وروڼو او خوېندو سره مينه کوُو، نو د دې نه دا پته لګيږى چې مونږ د مرګ نه ژوند کښې داخل شوى يُو. خو هغه څوک چې مينه په کښې نۀ وى هغه لا تر اوسه د مرګ په حالت کښې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29461, '1 John 3:15', '1 John', 3, 15, '&nbsp;هر څوک چې د خپل ورور يا خور نه نفرت کوى، قاتل دے، او تاسو ته پته ده چې قاتلانو کښې د تل ژوندون نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29462, '1 John 3:16', '1 John', 3, 16, '&nbsp;په دې وجه مونږ پوهيږو چې مينه څۀ ده، ځکه چې مسيح زمونږ دپاره خپل ځان ورکړو. او مونږ ته هم په کار دى چې خپل ځانونه د خپلو وروڼو دپاره ورکړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29463, '1 John 3:17', '1 John', 3, 17, '&nbsp;کۀ د چا سره د دُنيا هر څيز وى او خپل ايماندار ورور يا خور ضرورتمند وګورى او د خپل زړۀ دروازه هغۀ ته بنده کړى نو بيا په هغۀ کښې د خُدائ پاک مينه څنګه اوسيږى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29464, '1 John 3:18', '1 John', 3, 18, '&nbsp;ګرانو بچو، مونږ دې صرف په خوله مينه نۀ کوُو، بلکې په رښتيا او په عملى طور دې کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29465, '1 John 3:19', '1 John', 3, 19, '&nbsp;نو په هم دې به مونږ پوهه شُو چې مونږ رښتينى يُو او خپل زړونه به د هغۀ په وړاندې مطمئن ساتو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29466, '1 John 3:20', '1 John', 3, 20, '&nbsp;کله چې زمونږ زړۀ مونږ ملامتوى نو خُدائ پاک زمونږ د زړۀ نه ډېر لوئ دے او هغه په هر څۀ خبر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29467, '1 John 3:21', '1 John', 3, 21, '&nbsp;ګرانو دوستانو، کۀ زمونږ زړۀ مونږ نۀ ملامتوى نو بيا مونږ د خُدائ پاک په مخکښې پوره ډاډه يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29468, '1 John 3:22', '1 John', 3, 22, '&nbsp;او مونږ چې څۀ هم د هغۀ نه وغواړو هغه يې راکوى، ځکه چې مونږ د هغۀ په حُکمونو عمل کوُو او په څۀ چې هغه خوشحاليږى هم هغه کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29469, '1 John 3:23', '1 John', 3, 23, '&nbsp;او دا د هغۀ حُکم دے چې مونږ د هغۀ د زوئ عيسىٰ مسيح په نوم ايمان راوړُو او د هغۀ د حُکم په مطابق د يو بل سره مينه کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29470, '1 John 3:24', '1 John', 3, 24, '&nbsp;هغوئ څوک چې د خُدائ پاک په حُکمونو عمل کوى نو هغوئ په خُدائ پاک کښې اوسيږى او خُدائ پاک په هغوئ کښې اوسيږى. نو بيا به مونږ څۀ پوهه شُو چې هغه په مونږ کښې اوسيږى؟ مونږ د هغه روح په وسيله پرې پوهيږو کوم چې هغۀ مونږ له راکړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29471, '1 John 4:1', '1 John', 4, 1, '&nbsp;ګرانو دوستانو، په هر چا يقين مۀ کوئ څوک چې دا دعوىٰ کوى چې هغه د خُدائ د روح نه خبرې کوى بلکې تاسو هر يو کس آزمايئ چې هغه روح د خُدائ پاک د طرفه دے او کۀ نه، ځکه چې ډېر دروغژن نبيان په دُنيا کښې راپېدا شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29472, '1 John 4:2', '1 John', 4, 2, '&nbsp;نو دغه شان به مونږ په دې پوهه شُو چې کۀ چرې هغوئ سره د خُدائ پاک روح وى نو چې هغوئ دا اِقرار کوى چې عيسىٰ مسيح په انسانى شکل کښې راغلے دے، نو هغه روح د خُدائ پاک د طرفه دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29473, '1 John 4:3', '1 John', 4, 3, '&nbsp;او هر هغه څوک چې د عيسىٰ اِقرار نۀ کوى، نو هغه د خُدائ پاک د طرفه نۀ دے. نو په داسې کس کښې خردجال روح دے، د کوم په حقله چې تاسو ته وئيلے شوى دى چې هغه راتلونکے دے، خو هغه اوس دُنيا ته راغلے هم دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29474, '1 John 4:4', '1 John', 4, 4, '&nbsp;خو زما بچو، تاسو د خُدائ پاک د خاندان نه يئ او تاسو په دې دروغژنو نبيانو کامياب شوى يئ، ځکه چې هغه روح چې په تاسو کښې دے، هغه د هغه روح نه ډېر زورَور دے چې په دُنيا کښې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29475, '1 John 4:5', '1 John', 4, 5, '&nbsp;هغوئ د دُنيا دى نو ځکه دُنياوى خبرې کوى، نو ځکه دُنيا هم هغوئ ته توجو ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29476, '1 John 4:6', '1 John', 4, 6, '&nbsp;خو مونږ د خُدائ پاک يُو او څوک چې خُدائ پاک پېژنى هغه زمونږ خبرې اورى، او څوک چې د خُدائ پاک نۀ دى، هغه زمونږ خبرې نۀ اورى. دغه شان مونږ د حقيقى او دروغژن روح تر مينځه فرق کولے شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29477, '1 John 4:7', '1 John', 4, 7, '&nbsp;ګرانو دوستانو، راځئ چې د يو بل سره مينه وکړُو ځکه چې مينه د خُدائ پاک د طرفه ده، او هر څوک چې مينه کوى هغه د خُدائ پاک روحانى بچى دى او خُدائ پاک پېژنى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29478, '1 John 4:8', '1 John', 4, 8, '&nbsp;خو څوک چې مينه نۀ کوى هغه خُدائ پاک نۀ پېژنى، ځکه چې خُدائ پاک مينه دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29479, '1 John 4:9', '1 John', 4, 9, '&nbsp;او د خُدائ پاک مينه زمونږ په مينځ کښې داسې ښکاره شوه چې خُدائ پاک دې دُنيا ته خپل يک يو زوئ راولېږلو چې مونږ د هغۀ په وسيله ژوندون ولرو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29480, '1 John 4:10', '1 John', 4, 10, '&nbsp;رښتينې مينه په دې کښې نۀ ده چې مونږ د خُدائ پاک سره مينه وکړه بلکې په دې کښې ده چې هغۀ مونږ سره مينه وکړه، او زمونږ د ګناهونو د کفارې دپاره هغۀ خپل زوئ راولېږلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29481, '1 John 4:11', '1 John', 4, 11, '&nbsp;ګرانو دوستانو، نو چې خُدائ پاک مونږ سره دومره ډېره مينه وکړه نو بيا مونږ ته هم په کار دى چې د يو بل سره مينه وکړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29482, '1 John 4:12', '1 John', 4, 12, '&nbsp;خُدائ پاک هيچا هم ليدلے نۀ دے، کۀ مونږ د يو بل سره مينه کوُو نو خُدائ پاک په مونږ کښې اوسيږى او د هغۀ مينه په مونږ کښې کامله شوې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29483, '1 John 4:13', '1 John', 4, 13, '&nbsp;په دې وجه مونږ ته پته ده چې مونږ په هغۀ کښې اوسيږو او هغه په مونږ کښې اوسيږى ځکه چې هغۀ مونږ له خپل روحُ القُدس راکړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29484, '1 John 4:14', '1 John', 4, 14, '&nbsp;او مونږ دا په خپلو سترګو وليدل او دا ګواهى ورکوو چې پلار خپل زوئ د دُنيا د خلاصونکى په طور راولېږلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29485, '1 John 4:15', '1 John', 4, 15, '&nbsp;څوک چې دا اِقرار کوى چې عيسىٰ د خُدائ پاک زوئ دے نو خُدائ پاک په هغۀ کښې او هغه په خُدائ پاک کښې اوسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29486, '1 John 4:16', '1 John', 4, 16, '&nbsp;نو دغه شان مونږ ته پته ده او په دې يقين کوُو چې خُدائ پاک مونږ سره مينه کوى. خُدائ پاک مينه دے او څوک چې په مينه کښې اوسى، هغه په خُدائ پاک کښې او خُدائ پاک په هغۀ کښې اوسيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29487, '1 John 4:17', '1 John', 4, 17, '&nbsp;او په دې طريقه مينه په مونږ کښې کامله شوې ده د دې دپاره چې د عدالت په ورځ مونږ زړۀور يُو، نو دا ځکه چې مونږ په دُنيا کښې د عيسىٰ په شان ژوند تېروو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29488, '1 John 4:18', '1 John', 4, 18, '&nbsp;په مينه کښې هيڅ يره نشته، خو کامله مينه يره اخوا کوى ځکه چې يره د سزا سره تعلق ساتى. او هر څوک چې يريږى، په هغۀ کښې مينه کامله شوې نۀ ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29489, '1 John 4:19', '1 John', 4, 19, '&nbsp;مونږ ځکه مينه کوُو چې خُدائ پاک اول مونږ سره مينه وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29490, '1 John 4:20', '1 John', 4, 20, '&nbsp;خو هغه څوک چې دا دعوىٰ کوى چې، ”زۀ د خُدائ پاک سره مينه کوم،“ او د خپل ورور او يا خور نه نفرت کوى نو هغه دروغژن دے، نو ځکه کوم خلق چې وينو او د هغوئ سره مينه نۀ کوُو نو دا نۀ شى کېدے چې د ناليدلى خُدائ پاک سره مينه وکړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29491, '1 John 4:21', '1 John', 4, 21, '&nbsp;دا حُکم مونږ ته د خُدائ پاک نه راکړے شوے دے، څوک چې د خُدائ پاک سره مينه کوى، نو د خپلو وروڼو او خوېندو سره دې هم مينه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29492, '1 John 5:1', '1 John', 5, 1, '&nbsp;د چا چې دا ايمان وى چې عيسىٰ هم مسيح دے، هغه د خُدائ پاک روحانى بچے دے. او هر څوک چې د پلار سره مينه کوى هغه د هغۀ د بچى سره هم مينه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29493, '1 John 5:2', '1 John', 5, 2, '&nbsp;هم د دې نه مونږ ته پته لګى چې مونږ د خُدائ پاک روحانى بچو سره مينه کوُو، کله چې مونږ خُدائ پاک سره مينه کوُو او د هغۀ په حکمونو عمل کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29494, '1 John 5:3', '1 John', 5, 3, '&nbsp;ځکه چې د خُدائ پاک مينه دا ده چې مونږ د هغۀ په حُکمونو عمل وکړو. او د هغۀ حُکمونه څۀ پيټے نۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29495, '1 John 5:4', '1 John', 5, 4, '&nbsp;ځکه چې د خُدائ پاک هر يو روحانى بچے په دُنيا غالب شوے دے. او دا هغه کاميابى ده کومه چې د ايمان په وسيله مونږ حاصله کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29496, '1 John 5:5', '1 John', 5, 5, '&nbsp;هغه څوک دى چې په دُنيا فتح حاصلوى بغېر د هغوئ نه د چا چې په دې ايمان دے چې عيسىٰ د خُدائ پاک زوئ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29497, '1 John 5:6', '1 John', 5, 6, '&nbsp;عيسىٰ مسيح هغه څوک دے چې د اوبو د بپتسمې او د وينې توېدلو سره راغے، او عيسىٰ مسيح يواځې د اوبو سره نه، بلکې د اوبو او د وينې سره راغے. او روحُ القُدس د دې خبرې ګواهى کوى ځکه چې روحُ القُدس حقيقت دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29498, '1 John 5:7', '1 John', 5, 7, '&nbsp;نو درې ګواهان دى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29499, '1 John 5:8', '1 John', 5, 8, '&nbsp;يعنې روحُ القُدس، اوبۀ او وينه، او د درېو واړو يوه خبره ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(29500, '1 John 5:9', '1 John', 5, 9, '&nbsp;مونږ د انسان ګواهى قبلوُو خو د خُدائ پاک ګواهى د انسان په نسبت ډېره ښۀ ده او د خُدائ ګواهى دا ده چې هغۀ د خپل زوئ تصديق وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');